#!/bin/sh
# Builds the signed Slack App with its page as a self-contained client view, for the native-open drill.
# Run through cargo-slot.sh from the repository root with CHARIOX_APP_TOOLCHAIN, CHARIOX_APP_COMPONENT_CHECK
# and TMPDIR set as in packages/app-sdk-tools/README.md; every generated byte stays in the output directory,
# which must be outside the checkout.
# usage: build-package.sh <absolute output directory>
set -eu
: "${CARGO_TARGET_DIR:?use cargo-slot.sh}"
output=${1:?usage: build-package.sh <absolute output directory>}
case "$output" in /*) ;; *) echo 'The output directory must be absolute' >&2; exit 2;; esac
root=$(pwd)
case "$output/" in "$root/"*) echo 'The output directory must be outside the checkout' >&2; exit 2;; esac
app=examples/apps/slack
mkdir -p "$output"
node packages/app-sdk-tools/build-js.mjs "$app/app.ts" "$output/slack.core.wasm"
node "$app/scripts/build-view.mjs" "$output/view"
cargo run --locked -p chariox-app-wasm-worker --example client-view-package -- "$output/slack.core.wasm" "$output/view/index.html" "$app" "$output"
